import { createContext, useContext, useMemo } from 'react';
import { getMenuItems } from '../utils/menu.js';
import { useLocation } from '../shared/router.js';
export const ShowcaseContext = createContext({
  processedProps: {
    stories: [],
    defineStoryUrl: () => '/',
    storySearch: false
  },
  menuOpen: false,
  toggleMenu() {},
  defaultPathname: ''
});
ShowcaseContext.displayName = 'ShowcaseContext';
export function useStories() {
  const {
    processedProps
  } = useContext(ShowcaseContext);
  const {
    stories
  } = processedProps;
  return stories;
}
export function useCurrentStory() {
  const location = useLocation();
  const {
    processedProps
  } = useContext(ShowcaseContext);
  const {
    stories
  } = processedProps;
  return useMemo(() => stories.find(item => item.pathname === location.pathname), [stories, location.pathname]);
}
export function useMenuItems() {
  const {
    processedProps
  } = useContext(ShowcaseContext);
  const {
    stories
  } = processedProps;
  return useMemo(() => getMenuItems(stories), [stories]);
}
export function useMainMenu() {
  const {
    menuOpen,
    toggleMenu
  } = useContext(ShowcaseContext);
  return useMemo(() => [menuOpen, toggleMenu], [menuOpen, toggleMenu]);
}
export function useStorySearchResult(query) {
  const {
    processedProps
  } = useContext(ShowcaseContext);
  const {
    stories
  } = processedProps;
  return useMemo(() => {
    if (!query) {
      return stories;
    }
    return stories.filter(({
      meta
    }) => !meta?.menuHidden && (meta?.title?.toLowerCase().includes(query.toLowerCase()) || meta?.category?.toLowerCase().includes(query.toLowerCase())));
  }, [query, stories]);
}