import { StoryModuleSchema } from '../core/index.js';
export function filterValidStories(stories) {
  const validStories = [];
  const invalidStories = [];
  for (const item of stories) {
    const parseResult = StoryModuleSchema.safeParse(item);
    if (parseResult.success) {
      validStories.push(parseResult.data);
    } else {
      invalidStories.push(item);
    }
  }
  return {
    validStories,
    invalidStories
  };
}