import { createContext, useCallback, useContext, useEffect, useState } from 'react';
export class QueryRouter {
  location;
  listeners;
  constructor() {
    this.location = {
      pathname: ''
    };
    this.listeners = new Set();
  }
  updateLocation(pathname) {
    this.location = {
      pathname
    };
    this.listeners.forEach(fn => fn());
  }
  getLocation() {
    return this.location;
  }
  navigate(pathname) {
    const url = new URL(window.location.href);
    url.searchParams.delete('path');
    window.history.pushState(null, '', `${url.pathname}${url.search}${pathname ? `${url.search ? '&' : '?'}path=${pathname}` : ''}`);
    this.updateLocation(pathname);
  }
  connect() {
    const sync = () => {
      // @todo проверить event.target тк iframe на странице тоже вызывает событие на родителе
      this.updateLocation(new URL(window.location.href).searchParams.get('path') ?? '');
    };
    window.addEventListener('popstate', sync);
    sync();
    return () => {
      window.removeEventListener('popstate', sync);
    };
  }
  subscribe(listener) {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }
}
export const RouterContext = createContext({
  getLocation: () => ({
    pathname: ''
  }),
  navigate: () => {},
  subscribe: () => () => {},
  connect: () => () => {}
});
RouterContext.displayName = 'RouterContext';
export function useNavigate() {
  const router = useContext(RouterContext);
  return useCallback(pathname => router.navigate(pathname), [router]);
}
export function useLocation() {
  const router = useContext(RouterContext);
  const [location, setLocation] = useState(() => ({
    pathname: ''
  }));
  useEffect(() => {
    const sync = () => {
      setLocation(router.getLocation());
    };
    sync();
    return router.subscribe(sync);
  }, [router]);
  return location;
}